from pathlib import Path
ROOT=Path.cwd()
FILES={
    'server/src/modules/module-standards/module-standards.service.ts': "/** Read-only projections of the System Workflow Rule Registry. */\nimport { Injectable, OnModuleInit } from '@nestjs/common';\nimport { SEED_MODULE_STANDARDS } from './module-standards.seed';\nimport { standardDirectiveCache } from './standard-directive.cache';\nimport {\n  SYSTEM_WORKFLOW_RULESET_VERSION,\n  activeSystemWorkflowRules,\n  getSystemWorkflowRule,\n  systemWorkflowRuleDependents,\n  systemWorkflowRuleDependencies,\n} from './system-workflow-rules.registry';\nimport type { SystemWorkflowRule } from './system-workflow-rule.types';\n\n@Injectable()\nexport class ModuleStandardsService implements OnModuleInit {\n  onModuleInit(): void { this.loadToCache(); }\n\n  loadToCache(): void {\n    standardDirectiveCache.rebuild(activeSystemWorkflowRules());\n  }\n\n  private ruleView(rule: SystemWorkflowRule) {\n    return {\n      id: rule.id,\n      name: rule.name,\n      category: rule.category,\n      level: rule.level,\n      status: rule.status,\n      blocking: rule.blocking,\n      summary: rule.summary,\n      details: [...(rule.details ?? [])],\n      scenarios: [...rule.scenarios],\n      consumers: [...rule.consumers],\n      evidencePolicy: rule.evidencePolicy ?? null,\n      parameterRefs: [...(rule.parameterRefs ?? [])],\n      dependencies: [...(rule.dependencies ?? [])],\n      dependents: systemWorkflowRuleDependents(rule.id).map((item) => item.id),\n      implementationRefs: [...rule.implementationRefs],\n      testRefs: [...(rule.testRefs ?? [])],\n      directives: rule.directives ? structuredClone(rule.directives) : null,\n      rulesetVersion: SYSTEM_WORKFLOW_RULESET_VERSION,\n      source: 'system_workflow_rule_registry',\n    };\n  }\n\n  listRules() {\n    return [...activeSystemWorkflowRules()]\n      .sort((a, b) => `${a.category}:${a.id}`.localeCompare(`${b.category}:${b.id}`))\n      .map((item) => this.ruleView(item));\n  }\n\n  getRule(id: string) {\n    const item = getSystemWorkflowRule(id);\n    if (!item || item.status !== 'active') return null;\n    return this.ruleView(item);\n  }\n\n  impact(id: string) {\n    const item = getSystemWorkflowRule(id);\n    if (!item) return null;\n    return {\n      rule: this.ruleView(item),\n      dependencies: systemWorkflowRuleDependencies(id).map((rule) => this.ruleView(rule)),\n      dependents: systemWorkflowRuleDependents(id).map((rule) => this.ruleView(rule)),\n    };\n  }\n\n  /** Backward-compatible grouped view; groups are filters, never rule owners. */\n  list() {\n    return SEED_MODULE_STANDARDS.map((standard) => ({\n      moduleKey: standard.module_key,\n      moduleName: standard.module_name,\n      category: standard.category,\n      scenarios: [...standard.scenarios],\n      businessTables: [...standard.business_tables],\n      purpose: standard.purpose,\n      steps: structuredClone(standard.steps),\n      requirements: [...standard.requirements],\n      rules: [...standard.rules],\n      qualityBar: standard.quality_bar,\n      inputs: [...standard.inputs],\n      outputs: [...standard.outputs],\n      version: SYSTEM_WORKFLOW_RULESET_VERSION,\n      changeNote: `Registry 只读投影 v${SYSTEM_WORKFLOW_RULESET_VERSION}`,\n      source: 'system_workflow_rule_registry',\n      seedBaselineVersion: SYSTEM_WORKFLOW_RULESET_VERSION,\n      updatedAt: null,\n    }));\n  }\n\n  get(moduleKey: string) {\n    return this.list().find((item) => item.moduleKey === moduleKey) ?? null;\n  }\n\n  status() {\n    return {\n      running: [],\n      recent: [],\n      modules: this.list().map((item) => ({\n        moduleKey: item.moduleKey,\n        moduleName: item.moduleName,\n        category: item.category,\n        version: item.version,\n        running: false,\n        dirty: false,\n        reasons: [],\n        lastSummarizedAt: null,\n      })),\n      ruleCount: activeSystemWorkflowRules().length,\n      dirtyCount: 0,\n      standardSource: 'system_workflow_rule_registry',\n      rulesetVersion: SYSTEM_WORKFLOW_RULESET_VERSION,\n      seedBaselineVersion: SYSTEM_WORKFLOW_RULESET_VERSION,\n      cacheRebuiltAt: standardDirectiveCache.getRebuiltAt(),\n    };\n  }\n}\n",
    'server/src/chain/real-llm.standards.spec.ts': "import { afterEach, expect, it, vi } from 'vitest';\nimport { RealLLMService } from './real-llm.service';\nimport { standardDirectiveCache } from '../modules/module-standards/standard-directive.cache';\nimport { activeSystemWorkflowRules, SYSTEM_WORKFLOW_RULESET_VERSION } from '../modules/module-standards/system-workflow-rules.registry';\n\nafterEach(() => standardDirectiveCache.clear());\n\nit('injects Rule-ID based public standards with preserved detailed clauses', async () => {\n  standardDirectiveCache.rebuild(activeSystemWorkflowRules());\n  const service = new RealLLMService({\n    getConfig: () => ({ defaults: { maxTokens: 4096 } }),\n    getModelForScenario: () => ({ modelName: 'fixture', modelVersion: 'fixture', temperature: 0 }),\n  } as any, { beginRun: vi.fn(), finishRun: vi.fn() } as any);\n  const call = vi.fn(async () => ({ content: '{}', finishReason: 'stop' }));\n  (service as any).callModel = call;\n\n  await service.generate({ prompt: '评审正文', scenario: 'review', responseFormat: 'json_object' });\n  const system = (call.mock.calls.at(-1) as any)[2] as string;\n  expect(system).toContain('【系统规则 ARCH-003');\n  expect(system).toContain('【系统规则 QLT-011');\n  expect(system).toContain('prosePassed');\n  expect(system).toContain('【系统规则 QLT-012');\n  expect(system).toContain('具体必需事件');\n  expect(system).toContain('终章以收束和兑现为优先');\n  expect(system).toContain('不得为了换词强加感官或身体动作');\n});\n\nit('injectStandard=false really disables public-rule injection instead of leaving a second inline preflight rule', async () => {\n  standardDirectiveCache.rebuild(activeSystemWorkflowRules());\n  const service = new RealLLMService({\n    getConfig: () => ({ defaults: { maxTokens: 4096 } }),\n    getModelForScenario: () => ({ modelName: 'fixture', modelVersion: 'fixture', temperature: 0 }),\n  } as any, { beginRun: vi.fn(), finishRun: vi.fn() } as any);\n  const call = vi.fn(async () => ({ content: '结果', finishReason: 'stop' }));\n  (service as any).callModel = call;\n  await service.generate({ prompt: '题材', scenario: 'idea_generate', injectStandard: false });\n  const system = (call.mock.calls[0] as any)[2] as string;\n  expect(system).not.toContain('执行前置规则');\n  expect(system).not.toContain('【系统规则');\n});\n\nit('ruleset snapshots carry both scene digest and registry-wide digest', () => {\n  standardDirectiveCache.rebuild(activeSystemWorkflowRules());\n  const snapshot = standardDirectiveCache.snapshot('writing', true);\n  expect(snapshot.rulesetVersion).toBe(SYSTEM_WORKFLOW_RULESET_VERSION);\n  expect(snapshot.digest).toMatch(/^[a-f0-9]{64}$/);\n  expect(snapshot.registryDigest).toMatch(/^[a-f0-9]{64}$/);\n  expect(snapshot.ruleIds).toContain('GEN-004');\n  expect(snapshot.ruleIds).toContain('QLT-013');\n});\n\nit('normalized daily body steps still receive writing rules from the single registry', () => {\n  standardDirectiveCache.rebuild(activeSystemWorkflowRules());\n  expect(standardDirectiveCache.get('daily', 'body_first')).toContain('【系统规则 GEN-004');\n  expect(standardDirectiveCache.snapshot('daily', true, 'body_first').available).toBe(true);\n});\n",
    'server/src/chain/source-fact-consistency.spec.ts': "import { describe, expect, it } from 'vitest';\nimport { detectStructuredFactConflicts } from './source-fact-consistency';\n\ndescribe('CTX-005 structured fact consistency', () => {\n  it('blocks contradictory values only after the caller provides the same stable fact identity', () => {\n    const conflicts = detectStructuredFactConflicts([\n      { identity: 'deadline:permit', kind: 'duration_hours', value: 24, source: 'canon', certainty: 'explicit' },\n      { identity: 'deadline:permit', kind: 'duration_hours', value: 72, source: 'chapter-plan', certainty: 'derived' },\n    ]);\n    expect(conflicts).toHaveLength(1);\n    expect(conflicts[0].ruleId).toBe('CTX-005');\n  });\n\n  it('does not invent a conflict for different fact identities or incompatible units', () => {\n    expect(detectStructuredFactConflicts([\n      { identity: 'inventory:a', kind: 'number', value: 3, unit: 'box', source: 'canon' },\n      { identity: 'inventory:b', kind: 'number', value: 4, unit: 'box', source: 'plan' },\n    ])).toEqual([]);\n    expect(detectStructuredFactConflicts([\n      { identity: 'inventory:a', kind: 'number', value: 3, unit: 'box', source: 'canon' },\n      { identity: 'inventory:a', kind: 'number', value: 3, unit: 'item', source: 'plan' },\n    ])).toEqual([]);\n  });\n\n  it('works for location/state without story-specific vocabulary', () => {\n    expect(detectStructuredFactConflicts([\n      { identity: 'character:lead:location', kind: 'location', value: 'A地', source: 'accepted-canon' },\n      { identity: 'character:lead:location', kind: 'location', value: 'B地', source: 'chapter-plan' },\n    ])).toHaveLength(1);\n  });\n});\n",
    'server/src/modules/module-standards/module-standards.controller.ts': "/** Read-only API for the System Workflow Rule Registry. */\nimport { Controller, Get, Param } from '@nestjs/common';\nimport { ApiTags } from '@nestjs/swagger';\nimport { ModuleStandardsService } from './module-standards.service';\n\n@ApiTags('module-standards')\n@Controller('module-standards')\nexport class ModuleStandardsController {\n  constructor(private readonly service: ModuleStandardsService) {}\n\n  /** Compatibility grouped view. */\n  @Get()\n  list() { return { standards: this.service.list() }; }\n\n  @Get('rules')\n  rules() { return { rules: this.service.listRules() }; }\n\n  @Get('rules/:id')\n  rule(@Param('id') id: string) {\n    const value = this.service.getRule(id);\n    return value ? { rule: value } : { error: 'not found', rule: null };\n  }\n\n  @Get('rules/:id/impact')\n  impact(@Param('id') id: string) {\n    const value = this.service.impact(id);\n    return value ? { impact: value } : { error: 'not found', impact: null };\n  }\n\n  @Get('status')\n  status() { return this.service.status(); }\n\n  @Get(':key')\n  one(@Param('key') key: string) {\n    const standard = this.service.get(key);\n    return standard ? { standard } : { error: 'not found', standard: null };\n  }\n}\n",
    'server/src/chain/source-countdown-consistency.spec.ts': "import { describe, expect, it } from 'vitest';\nimport { detectSourceCountdownRisk } from './source-countdown-consistency';\n\ndescribe('generic countdown/deadline advisory', () => {\n  it('surfaces arithmetic risk without story nouns when the raw text appears inconsistent', () => {\n    expect(detectSourceCountdownRisk('', '现在上午十点，三天后上午十点截止，剩余七十二小时。')).toBeNull();\n    expect(detectSourceCountdownRisk('', '现在晚上八点，三天后上午十点截止，剩余七十二小时。')).toContain('风险');\n  });\n\n  it('does not guess when identity/arithmetic anchors are incomplete', () => {\n    expect(detectSourceCountdownRisk('', '三天后上午十点截止；另一个流程每次延后一小时。')).toBeNull();\n    expect(detectSourceCountdownRisk('三年前发生过事故。', '三天后截止。')).toBeNull();\n  });\n\n  it('is explicitly advisory because raw text has no stable fact identity', () => {\n    const source = detectSourceCountdownRisk.toString();\n    expect(source).not.toMatch(/爆破|起爆|进门|回拨|扣名/);\n  });\n});\n",
    'server/src/modules/module-standards/system-workflow-rules.registry.ts': "/** Compatibility re-export. The machine rule projection is owned by server/shared/src. */\nexport * from '../../../shared/src/system-workflow-rules.registry';\n",
}
for rel,content in FILES.items():
    p=ROOT/rel; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(content,encoding="utf-8")
print(f"wrote {len(FILES)} files")
